/**
 * Generates the phone app's project icons from the desktop's own path data, so a
 * project shows the same icon on both apps:
 *
 *   src/lib/project-icon-paths.ts -> android/.../phone/ProjectIcons.kt
 *
 * Run: node scripts/generate-android-project-icons.mjs [--check]
 *
 * `--check` verifies the generated file is current without writing, which is how
 * LookPresetsGeneratedTest keeps the two apps honest.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import process from 'node:process';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(root, 'src/lib/project-icon-paths.ts');
const OUT = join(root, 'android/app/src/main/java/com/parallelcode/phone/ProjectIcons.kt');

/** Reads `id: ['path', ...]` entries; quoted ids such as `'file-code'` included. */
function readIcons(source) {
  const icons = [];
  for (const match of source.matchAll(/^ {2}'?([a-z0-9-]+)'?: \[\n([\s\S]*?)\n {2}\],$/gm)) {
    const paths = [...match[2].matchAll(/'([^']*)'/g)].map((m) => m[1]);
    if (!paths.length) throw new Error(`Icon ${match[1]} has no paths`);
    icons.push({ id: match[1], paths });
  }
  if (!icons.length) throw new Error(`No icons found in ${SOURCE}`);
  return icons;
}

function render(icons) {
  const entries = icons.map(
    ({ id, paths }) => `    "${id}" to listOf(${paths.map((p) => `"${p}"`).join(', ')}),`,
  );
  return `// Generated by scripts/generate-android-project-icons.mjs from src/lib/project-icon-paths.ts.
// Do not edit; run node scripts/generate-android-project-icons.mjs after the desktop's icons change.
// Icon paths from @primer/octicons (MIT, Copyright (c) GitHub Inc.).
package com.parallelcode.phone

/** SVG path data (16×16 viewBox) for each desktop project icon, by id. */
internal val PROJECT_ICON_PATHS: Map<String, List<String>> = mapOf(
${entries.join('\n')}
)
`;
}

const icons = readIcons(readFileSync(SOURCE, 'utf8'));
const generated = render(icons);
const relativeOut = OUT.slice(root.length + 1);

if (process.argv.includes('--check')) {
  let current = null;
  try {
    current = readFileSync(OUT, 'utf8');
  } catch {
    current = null;
  }
  if (current !== generated) {
    console.error(
      `${relativeOut} is missing or out of date with src/lib/project-icon-paths.ts.\n` +
        'Run: node scripts/generate-android-project-icons.mjs',
    );
    process.exit(1);
  }
  console.log(`${relativeOut} is up to date (${icons.length} icons).`);
} else {
  writeFileSync(OUT, generated);
  console.log(`Wrote ${relativeOut} (${icons.length} icons).`);
}
